// RegisterStatusActivity registers a kube.v1.Status activity
func RegisterStatusActivity(r worker.ActivityRegistry, fn func(context.Context, *StatusInput) (*StatusOutput, error)) {
	r.RegisterActivityWithOptions(fn, activity.RegisterOptions{
		Name: StatusActivityName,
	})
}

// StatusFuture describes a(n) kube.v1.Status activity execution
type StatusFuture struct {
	Future workflow.Future
}

// Get blocks on the activity's completion, returning the response
func (f *StatusFuture) Get(ctx workflow.Context) (*StatusOutput, error) {
	var resp StatusOutput
	if err := f.Future.Get(ctx, &resp); err != nil {
		return nil, err
	}
	return &resp, nil
}

// Select adds the activity's completion to the selector, callback can be nil
func (f *StatusFuture) Select(sel workflow.Selector, fn func(*StatusFuture)) workflow.Selector {
	return sel.AddFuture(f.Future, func(workflow.Future) {
		if fn != nil {
			fn(f)
		}
	})
}

